168	        integrity: { ...sealDefaults.integrity, iterations: 1 },
169	      },
170	    );
171	
172	    t.app.all("/strict", async (event) => {
173	      const session = await useSession(event, {
174	        ...sessionConfig,
175	        legacySealFallback: false,
176	      });
177	      return { session };
