179	
180	    const result = await t.fetch("/strict", {
181	      headers: { Cookie: `h3-test=${legacySealed}` },
182	    });
183	    const body = await result.json();
184	    expect(body.session.id).not.toBe("legacy");
185	    expect(body.session.data).toEqual({});
